import org.jsoup.Connection;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection.KeyVal keyVal;

    @Test
    public void constructorUrlBuilderTest() throws MalformedURLException {
        URL url = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(url);
        assertEquals(url, urlBuilder.build());
    }

    @Test
    public void buildTest() throws MalformedURLException {
        URL url = new URL("http://example.com/test");
        UrlBuilder urlBuilder = new UrlBuilder(url);
        URL result = urlBuilder.build();
        assertEquals(url, result);
    }

    @Test(expected = NullPointerException.class)
    public void constructorUrlBuilderNullUrlTest() {
        new UrlBuilder(null);
    }

    @Test(expected = IllegalStateException.class)
    public void appendKeyValWithoutCallingBuildTest() throws UnsupportedEncodingException {
        when(keyVal.key()).thenReturn("key");
        when(keyVal.value()).thenReturn("value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        urlBuilder.appendKeyVal(keyVal);
    }

    @Test
    public void appendKeyValBuildTest() throws MalformedURLException, UnsupportedEncodingException {
        when(keyVal.key()).thenReturn("key");
        when(keyVal.value()).thenReturn("value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://example.com"));
        urlBuilder.appendKeyVal(keyVal);
        URL urlWithParameter = urlBuilder.build();
        assertEquals("http://example.com/?key=value", urlWithParameter.toString());
    }
}
```
